use trustkit_orch::wave_board_server_sse::{SseEvent, WaveBoardServerSse};

#[tokio::test]
async fn test_task_002_red_phase_contract() {
    // Criterios: "Servidor HTTP Local com Endpoint SSE e Entrega do Dashboard"
    let html = "<html><body><h1>Wave Board Kanban</h1></body></html>";
    let server = WaveBoardServerSse::new(html);

    assert_eq!(server.dashboard_html(), html);

    let mut rx = server.subscribe();
    let event = SseEvent::new("mutation", "{\"task_id\":\"TASK-002\",\"status\":\"DONE\"}");
    let frame = event.to_sse_frame();

    assert!(frame.contains("event: mutation"));
    assert!(frame.contains("data: {\"task_id\":\"TASK-002\",\"status\":\"DONE\"}"));

    let count = server
        .broadcast(event.clone())
        .expect("Failed to broadcast SSE event");
    assert_eq!(count, 1);

    let received = rx.recv().await.expect("Failed to receive SSE event");
    assert_eq!(received, event);

    assert!(!event.event_type.is_empty(), "GREEN verified");
}
